draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // plant seed
  ctx.fillStyle = '#000';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 10, 0, 2 * Math.PI);
  ctx.fill();

  // growing plant
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/2 - 50 * (1 + Math.sin(t)));
  ctx.stroke();

  // leaves
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(W/2 - 20 * Math.sin(t), H/2 - 50 * (1 + Math.sin(t)) - 20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 20 * Math.sin(t), H/2 - 50 * (1 + Math.sin(t)) - 20, 10, 0, 2 * Math.PI);
  ctx.fill();

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H - 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50);
  ctx.lineTo(W/2, H - 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 100);
  ctx.lineTo(W/2 - 30, H - 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 100);
  ctx.lineTo(W/2 + 30, H - 70);
  ctx.stroke();

  // watering can
  ctx.beginPath();
  ctx.rect(W/2 - 40, H - 150, 20, 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 40, H - 130);
  ctx.lineTo(W/2 - 40, H - 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H - 130);
  ctx.lineTo(W/2, H - 120);
  ctx.stroke();

  ctx.restore();
}
